    /// <summary>
    /// Write the record
    /// </summary>
    void write()
    {
        FormDataSource              metInventTransferTableExt_ds;
        METInventTransferTableExt   metInventTransferTableExt;
        InventTransferTable         metInventTransferTable;

        next write();

        metInventTransferTableExt_ds = this.formRun().dataSource(formDataSourceStr(InventTransferOrders, METInventTransferTableExt));

        if (metInventTransferTableExt_ds)
        {
            metInventTransferTable      = this.cursor();
            metInventTransferTableExt   = metInventTransferTableExt_ds.cursor();
            
            metInventTransferTable.metPackMETInventTransferTableExt(metInventTransferTableExt);
            metInventTransferTableExt.SysExtensionSerializerExtensionMap::insertAfterBaseTable(metInventTransferTable);
        }

    }
